document.addEventListener("DOMContentLoaded",function(){const a=document.querySelectorAll(".tab-btn"),c=document.querySelectorAll(".tab-panel");a.forEach(function(e){e.addEventListener("click",function(){const s=e.getAttribute("data-tab");a.forEach(function(t){t.classList.remove("active"),t.setAttribute("aria-selected","false")}),e.classList.add("active"),e.setAttribute("aria-selected","true"),c.forEach(function(t){t.classList.remove("active"),t.id===s&&t.classList.add("active")})})})});
